**election.c**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define NB_CANDIDATS 7
#define LONG_NOM 50

int main(void)
{
    FILE *fin, *fout;
    char noms[NB_CANDIDATS][LONG_NOM];
    int scores[NB_CANDIDATS] = {0};
    int vote, total = 0, valides = 0, annules = 0;
    int i, max;

    fin = fopen("votes.txt", "r");
    if (fin == NULL) {
        printf("Erreur : impossible d'ouvrir votes.txt\n");
        return 1;
    }
    fout = fopen("resultats.txt", "w");
    if (fout == NULL) {
        printf("Erreur : impossible de creer resultats.txt\n");
        fclose(fin);
        return 1;
    }

    /* Lecture des noms (une ligne par candidat) */
    for (i = 0; i < NB_CANDIDATS; i++) {
        if (fgets(noms[i], LONG_NOM, fin) == NULL) {
            printf("Erreur : fichier de noms incomplet\n");
            fclose(fin);
            fclose(fout);
            return 1;
        }
        noms[i][strcspn(noms[i], "\r\n")] = '\0';  /* enlever le retour a la ligne */
    }

    /* Lecture des votes */
    while (fscanf(fin, "%d", &vote) == 1) {
        total++;
        if (vote >= 1 && vote <= NB_CANDIDATS) {
            scores[vote - 1]++;
            valides++;
        } else {
            fprintf(fout, "Vote invalide : %d\n", vote);
            annules++;
        }
    }

    fprintf(fout, "Nombre d'electeurs : %d\n", total);
    fprintf(fout, "Nombre de votes valides : %d\n", valides);
    fprintf(fout, "Nombre de votes annules : %d\n\n", annules);

    fprintf(fout, "Candidat\t\tscore\n");
    for (i = 0; i < NB_CANDIDATS; i++)
        fprintf(fout, "%-20s\t%d\n", noms[i], scores[i]);

    /* Recherche du maximum */
    max = scores[0];
    for (i = 1; i < NB_CANDIDATS; i++)
        if (scores[i] > max)
            max = scores[i];

    /* Affichage des gagnants (plusieurs en cas d'égalité) */
    fprintf(fout, "\nLes gagnants:\n");
    for (i = 0; i < NB_CANDIDATS; i++)
        if (scores[i] == max)
            fprintf(fout, "%s\n", noms[i]);

    fclose(fin);
    fclose(fout);
    return 0;
}
```

